import{_ as n,C as i,o as s,c as r,a6 as l,E as o,j as t,a as u}from"./chunks/framework.CKIbuWFA.js";const b=JSON.parse('{"title":"Lire et examiner le flux LIVE","description":"","frontmatter":{"title":"Lire et examiner le flux LIVE","docId":"user.live.feed","translationKey":"user.live.feed","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4830f0a02244f46bfefb9b37c09d96c969688d022a0df90359c96c3e359af147","translationRevision":"e97c731542bee311a0618d9a8cfd28fbaafd42269b289da9c703b330e55ee895","order":20},"headers":[],"relativePath":"fr/user/live/feed.md","filePath":"fr/user/live/feed.md","lastUpdated":1794611623000}'),c={name:"fr/user/live/feed.md"};function d(p,e,m,f,v,h){const a=i("DemoFrame");return s(),r("div",null,[e[0]||(e[0]=l('<h1 id="read-and-inspect-the-live-feed" tabindex="-1">Lire et examiner le flux LIVE <a class="header-anchor" href="#read-and-inspect-the-live-feed" aria-label="Permalink to &quot;Lire et examiner le flux LIVE {#read-and-inspect-the-live-feed}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Trouver un événement, examiner ses champs et distinguer un affichage en pause d’une salle déconnectée. Commencez avec une <a href="./connections.html">connexion LIVE</a>, ou utilisez les événements déjà présents dans le flux actuel. Le flux est une vue de travail bornée, pas un enregistrement complet d’une diffusion.</p><h2 id="inspect-activity" tabindex="-1">Examiner l’activité <a class="header-anchor" href="#inspect-activity" aria-label="Permalink to &quot;Examiner l’activité {#inspect-activity}&quot;">​</a></h2><ol><li>Ouvrez <strong>Live feed</strong> et confirmez le créateur actif dans l’état de connexion.</li><li>Choisissez un filtre d’événements : tous, discussions, cadeaux, mentions J’aime, abonnements, arrivées ou autres activités sociales. Combinez-le avec la recherche pour trouver un auteur, un message, un nom de cadeau ou un identifiant exact de cadeau.</li><li>Sélectionnez <strong>Pause</strong> pour arrêter le défilement automatique pendant la lecture. Les événements peuvent continuer à arriver et le compteur de non lus augmenter. Cette commande ne déconnecte pas TikTok et ne suspend pas les automatisations.</li><li>Sélectionnez un événement pour ouvrir son inspecteur. Lisez son type et les détails disponibles avant de choisir les champs d’automatisation. Tous les événements ne contiennent pas de texte de discussion, d’informations de cadeau ou d’identité de spectateur.</li><li>Sélectionnez le nom ou l’avatar d’un spectateur pour examiner son profil suivi. Utilisez la commande de l’inspecteur si le panneau de détails est masqué.</li><li>Sélectionnez <strong>Resume</strong> ou le bouton d’accès aux événements non lus pour revenir à l’activité entrante. Effacez la recherche et choisissez tous les événements pour vérifier que de l’activité arrive.</li></ol><p>Utilisez autant que possible les commandes libellées avec le focus clavier. Suspendre le défilement aide lorsque le mouvement gêne la lecture. Un avatar absent est remplacé par des initiales ; une image n’est pas nécessaire pour identifier un spectateur.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Le filtrage et l’inspection sont disponibles. Lors d’un trafic important, l’interface peut afficher une fenêtre de rendu limitée et signaler des événements d’interface abandonnés. Ces indicateurs concernent l’affichage ; n’utilisez pas le nombre de lignes visibles comme total comptable. <a href="./../points/statistics.html">Analytics</a> interroge séparément les agrégats persistants.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Si le flux est vide, retirez les filtres, reprenez le défilement et vérifiez l’état de connexion. Une salle calme peut fonctionner normalement. La reconnexion au même créateur conserve le contexte ; changer de créateur le modifie. <strong>Clear</strong> vide le flux de travail sans réinitialiser les points ou les statistiques. Examinez les indicateurs de perte via les <a href="./../preferences/troubleshooting.html">diagnostics</a>, sans supposer que toutes les lignes manquantes à l’affichage sont des événements distants perdus.</p>',10)),o(a,{scenario:"feed",locale:"fr",title:"Démo : flux"}),e[1]||(e[1]=t("h2",{id:"operational-details",tabindex:"-1"},[u("Détails de fonctionnement "),t("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Détails de fonctionnement {#operational-details}"'},"​")],-1)),e[2]||(e[2]=t("p",null,"Cette version conserve au plus 300 événements affichés et en prépare jusqu’à 900 en attendant la présentation. Elle retire d’abord la plus ancienne ligne autre qu’un cadeau, puis les cadeaux seulement lorsqu’il ne reste aucun autre type. Un cadeau ancien peut donc survivre à un chat récent. Suspendre le défilement n’arrête pas l’entrée et ne garantit pas la conservation. Les filtres ne récupèrent pas les lignes retirées ; une perte ne permet pas de rejouer points ou actions.",-1))])}const g=n(c,[["render",d]]);export{b as __pageData,g as default};
